create or replace function public.v02_prepare_activity() returns trigger language plpgsql set search_path='' as $$begin new.occurred_at:=coalesce((new.details->>'contact_at')::timestamptz,new.occurred_at,new.created_at);if new.kind='created' then new.details:=new.details||jsonb_build_object('lead',(select to_jsonb(l) from public.leads l where l.id=new.lead_id));end if;return new;end$$;
